        // Datos intrínsecos compartidos (todos los Corolla tienen estos componentes)
        string marca = &quot;Toyota Corolla&quot;;
        string motor = &quot;Híbrido 1300 turbo&quot;;
        string llantas = &quot;Michelin&quot;;
